import json
from typing import List, Dict, Any


def verify_settlement_idempotency(input_str: str) -> str:
    """
    Verifies settlement idempotency from a JSON string of records.
    Returns a report string.
    """
    try:
        records = json.loads(input_str)
    except json.JSONDecodeError:
        return "Error: Invalid input"

    if not isinstance(records, list):
        return "Error: Invalid input"

    required_fields = {"id", "merchant_id", "idempotency_key", "amount"}
    for rec in records:
        if not isinstance(rec, dict):
            return "Error: Invalid input"
        if not required_fields.issubset(rec.keys()):
            return "Error: Invalid input"
        if not isinstance(rec["amount"], (int, float)):
            return "Error: Invalid input"

    # Group by idempotency_key
    groups: Dict[str, List[Dict[str, Any]]] = {}
    for rec in records:
        key = rec["idempotency_key"]
        groups.setdefault(key, []).append(rec)

    duplicates: List[str] = []
    conflicts: List[str] = []
    unique_settlements: List[Dict[str, Any]] = []

    for key, recs in groups.items():
        if len(recs) == 1:
            unique_settlements.append(recs[0])
        else:
            first = recs[0]
            unique_settlements.append(first)
            for rec in recs[1:]:
                if rec["amount"] == first["amount"]:
                    duplicates.append(rec["id"])
                else:
                    conflicts.append(rec["id"])

    # Per-merchant totals from unique settlements
    merchant_totals: Dict[str, float] = {}
    for rec in unique_settlements:
        mid = rec["merchant_id"]
        merchant_totals[mid] = merchant_totals.get(mid, 0) + rec["amount"]

    lines: List[str] = []
    for dup_id in duplicates:
        lines.append(f"Duplicate: id={dup_id}")
    for conf_id in conflicts:
        lines.append(f"Conflict: id={conf_id}")
    # Sort merchants for deterministic output (optional)
    for mid in sorted(merchant_totals.keys()):
        lines.append(f"Merchant {mid} total: {int(merchant_totals[mid])}")
    return "\n".join(lines)

